#!/usr/bin/env bash
# Writes deploy/compose/.env with fresh random secrets. Refuses to overwrite an existing file: the two
# key-encryption keys protect signing keys already stored in the database and must never change.
set -euo pipefail
OUT="$(cd "$(dirname "$0")" && pwd)/.env"
[ -e "$OUT" ] && { echo "$OUT exists; not overwriting (back it up, it holds your keys)" >&2; exit 1; }
r() { openssl rand -base64 32 | tr -d '\n'; }
umask 077
cat > "$OUT" <<ENV
# Generated by init-env.sh. Keep a backup: losing the two *_KEY_ENCRYPTION_KEY values makes stored signing keys unreadable.
TAG=${TAG:-latest-built-sha}
REGISTRY=${REGISTRY:-ghcr.io/dheerajmax3211/my-trove}
FIREBASE_PROJECT_ID=${FIREBASE_PROJECT_ID:-demo-platform}
# With the dev-idp profile: APP_FIREBASE_JWK_SET_URI=http://dev-idp:9100/jwks
APP_FIREBASE_JWK_SET_URI=
BOOTSTRAP_ADMIN_EMAILS=
WORKSPACE_URL=http://localhost:5190
SITE_URL=http://localhost:5191
API_URL=http://localhost:8080
BIND_ADDRESS=127.0.0.1
DB_PASSWORD=$(r)
APP_INTERNAL_API_KEY=$(r)
APP_PLATFORM_KEY_ENCRYPTION_KEY=$(r)
CONSENT_KEY_ENCRYPTION_KEY=$(r)
FILE_TOKEN_SECRET=$(r)
INBOUND_WEBHOOK_SECRET=$(r)
ENV
echo "wrote $OUT (mode 600). Set TAG to the image tag you deploy."
